const raw = $input.item.json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const isWebhook = Boolean(raw.headers || raw.body);

const name = String(body['Customer Name'] ?? body.customer_name ?? body.name ?? '').trim();
const email = String(body.Email ?? body.email ?? body.customer_email ?? '').trim().toLowerCase();
const company = String(body.Company ?? body.company ?? '').trim() || 'Unspecified';
const subject = String(body.Subject ?? body.subject ?? '').trim();
const message = String(body['Support Message'] ?? body.message ?? body.body_text ?? '').trim();
const urgencyHint = String(body['Urgency Hint'] ?? body.urgency_hint ?? body.urgency ?? 'Normal').trim();
const channel = String(body.channel || (isWebhook ? 'api_webhook' : 'support_form')).trim();

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const selfOrDaemon = /crm-notifications@example\.com|noreply@|no-reply@|mailer-daemon@|postmaster@/i.test(email);
const isValid = emailValid && !selfOrDaemon && subject.length >= 2 && message.length >= 3;

const nowIso = new Date().toISOString();
const ticketCode = String(body.ticket_code || `TKT-${Date.now().toString(36).toUpperCase()}`).trim().toUpperCase();

return {
  json: {
    trigger_source: isWebhook ? 'webhook' : 'form',
    is_valid: isValid,
    validation_error: !emailValid ? 'Valid customer email is required.' : (selfOrDaemon ? 'Blocked automated/self-reply sender.' : 'Subject and support message are required.'),
    ticket_code: ticketCode,
    customer_key: email,
    customer_name: name || (email ? email.split('@')[0] : 'Customer'),
    customer_email: email,
    company,
    subject,
    message,
    urgency_hint: urgencyHint,
    channel,
    created_at: nowIso,
    updated_at: nowIso,
  },
};

