parameters.jsCode:
const t = $('Normalize Support Ticket').item.json;
const cust = $('Lookup Customer Profile').item.json || {};
const raw = $input.item.json || {};
const ai = (raw.output && typeof raw.output === 'object') ? raw.output : raw;

const knownCustomer = Boolean(cust.customer_key || cust.id);
const subPlan = knownCustomer ? String(cust.subscription_plan || 'Active') : 'Unknown / Prospect';
const combinedText = `${t.subject} ${t.message} ${t.urgency_hint}`.toLowerCase();

const criticalMatch = /outage|production down|data loss|security|breach|legal|lawyer/i.test(combinedText);
const highMatch = /cancel|refund|chargeback|dispute|urgent|blocking|emergency/i.test(combinedText);
const aiFailed = Boolean(raw.error) || !ai.urgency;

let urgency = String(ai.urgency || 'MEDIUM').toUpperCase();
if (!['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'].includes(urgency)) urgency = 'MEDIUM';
if (criticalMatch) urgency = 'CRITICAL';
else if (highMatch && (urgency === 'LOW' || urgency === 'MEDIUM')) urgency = 'HIGH';
else if (aiFailed && urgency !== 'CRITICAL') urgency = 'HIGH';

const intent = String(ai.intent || (highMatch ? 'Cancellation / Dispute' : 'General Inquiry')).trim();
const humanIntervention = Boolean(ai.requires_escalation) || urgency === 'HIGH' || urgency === 'CRITICAL' || aiFailed;
const aiSummary = String(ai.ai_summary || t.subject).trim();
const aiDraftReply = String(ai.ai_draft_reply || `Thank you for contacting SaaS CRM support regarding "${t.subject}". Our engineering team has logged ticket ${t.ticket_code} and will follow up with concrete next steps shortly.`).trim();

const nowIso = new Date().toISOString();
const customerName = knownCustomer ? (cust.name || t.customer_name) : t.customer_name;
const nextOpenTickets = knownCustomer ? Number(cust.open_tickets_count || 0) + 1 : 0;
const nextTotalTickets = knownCustomer ? Number(cust.total_tickets_count || 0) + 1 : 0;
const ticketStatus = humanIntervention ? 'Escalated to Human' : 'Awaiting Approval';

const escHtml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const replyHtml = `
<div style="font-family:Inter,Segoe UI,Arial,sans-serif;max-width:600px;margin:0 auto;color:#111827;line-height:1.6;">
  <p>Hi ${escHtml(customerName)},</p>
  <p>${escHtml(aiDraftReply).replace(/\n/g, '<br>')}</p>
  <p style="font-size:12px;color:#64748b;margin-top:16px;">Ticket Reference: <code>${escHtml(t.ticket_code)}</code></p>
  <p>Best regards,<br><strong>SaaS CRM Support Team</strong></p>
</div>`.trim();

const escalationHtml = `<h2>[${escHtml(urgency)}] Support Escalation — ${escHtml(t.ticket_code)}</h2><p><strong>Customer:</strong> ${escHtml(customerName)} (${escHtml(t.customer_email)})</p><p><strong>CRM Account:</strong> ${knownCustomer ? escHtml(subPlan) + ' ($' + Number(cust.mrr_usd || 0) + '/mo MRR)' : 'Unknown / Prospect Sender'}</p><p><strong>Intent:</strong> ${escHtml(intent)} | <strong>Urgency:</strong> ${escHtml(urgency)}</p><p><strong>AI Summary:</strong> ${escHtml(aiSummary)}</p><p><strong>Message:</strong><br>${escHtml(t.message)}</p><p><strong>AI Draft Suggestion:</strong><br>${escHtml(aiDraftReply)}</p>`;

return {
  json: {
    trigger_source: t.trigger_source,
    ticket_code: t.ticket_code,
    customer_key: t.customer_key,
    customer_name: customerName,
    customer_email: t.customer_email,
    known_customer: knownCustomer,
    subscription_plan: subPlan,
    subject: t.subject,
    message: t.message,
    channel: t.channel,
    intent,
    urgency,
    ai_summary: aiSummary,
    ai_draft_reply: aiDraftReply,
    human_intervention: humanIntervention,
    ticket_status: ticketStatus,
    next_open_tickets: nextOpenTickets,
    next_total_tickets: nextTotalTickets,
    created_at: t.created_at,
    updated_at: nowIso,
    event_code: `SUP-${Date.now().toString(36).toUpperCase()}`,
    reply_html: replyHtml,
    escalation_html: escalationHtml,
    slack_message: `:ticket: *[${urgency}] Support Escalation — ${t.ticket_code}*\n*Sender:* ${customerName} (${t.customer_email}) | *Plan:* ${subPlan}\n*Intent:* ${intent}\n*Summary:* ${aiSummary}\n*Subject:* ${t.subject}`,
  },
};

